import boto3

def parse_amount(text):
    if not text:
        return None
    cleaned = text.replace(',', '').replace('$', '').replace('USD', '').strip()
    try:
        return float(cleaned)
    except ValueError:
        return None

def extract_and_normalize_expenses(document_bytes):
    client = boto3.client('textract')
    response = client.analyze_expense(
        Document={'Bytes': document_bytes},
        FeatureTypes=['EXPENSE_RECEIPTS', 'EXPENSE_INVOICES']
    )
    if not response.get('ExpenseDocuments'):
        return {}
    doc = response['ExpenseDocuments'][0]
    summary_fields = {}
    for field in doc.get('SummaryFields', []):
        field_name = field['Type']['Name']
        value = field['ValueDetection']['Text'].strip()
        summary_fields[field_name] = value
    line_items = []
    for group in doc.get('LineItemGroups', []):
        for line_item in group.get('LineItems', []):
            item_fields = {}
            for f in line_item.get('LineItemExpenseFields', []):
                fname = f['Type']['Name']
                fvalue = f['ValueDetection']['Text'].strip()
                item_fields[fname] = fvalue
            norm_item = {
                'description': item_fields.get('ITEM') or item_fields.get('DESCRIPTION', ''),
                'quantity': parse_amount(item_fields.get('QUANTITY')),
                'unit_price': parse_amount(item_fields.get('PRICE')),
                'amount': parse_amount(item_fields.get('TOTAL') or item_fields.get('LINE_ITEM_TOTAL', ''))
            }
            line_items.append(norm_item)
    normalized = {
        'vendor_name': (summary_fields.get('SUPPLIER_NAME') or
                        summary_fields.get('VENDOR_NAME') or
                        summary_fields.get('MERCHANT_NAME') or ''),
        'date': (summary_fields.get('RECEIPT_DATE') or
                 summary_fields.get('INVOICE_DATE') or
                 summary_fields.get('ORDER_DATE') or ''),
        'due_date': summary_fields.get('DUE_DATE', ''),
        'subtotal': parse_amount(summary_fields.get('SUBTOTAL')),
        'tax_amount': parse_amount(summary_fields.get('TAX') or summary_fields.get('TAX_TOTAL')),
        'tip_amount': parse_amount(summary_fields.get('TIP')),
        'total_amount': parse_amount(summary_fields.get('TOTAL')),
        'currency': summary_fields.get('CURRENCY_CODE', 'USD'),
        'line_items': line_items
    }
    return normalized
